CREATE TABLE IF NOT EXISTS feature_edits (id TEXT PRIMARY KEY, text TEXT, hidden INTEGER NOT NULL DEFAULT 0, updated_at TEXT, updated_by TEXT);
CREATE TABLE IF NOT EXISTS feature_custom (id INTEGER PRIMARY KEY AUTOINCREMENT, tile TEXT NOT NULL, text TEXT NOT NULL, added TEXT, hidden INTEGER NOT NULL DEFAULT 0, created_at TEXT, created_by TEXT);
CREATE TABLE IF NOT EXISTS feature_plans (id INTEGER PRIMARY KEY AUTOINCREMENT, tile TEXT NOT NULL, text TEXT NOT NULL, sort REAL NOT NULL DEFAULT 0, created_at TEXT, created_by TEXT, updated_at TEXT);
